WITH base AS (SELECT *, CASE WHEN dept_name IN ('Finance', 'Legal') THEN 'Core' ELSE 'Other' END AS dept_name_group, COALESCE(location, 'OTHER') AS resolved_location FROM departments WHERE location IS NOT NULL AND dept_name IS NOT DISTINCT FROM 'Legal') SELECT * FROM (SELECT location, dept_name, budget FROM base) src PIVOT (AVG(budget) AS amount FOR dept_name IN ('Sales' AS sales, 'Marketing' AS marketing));
